#pragma once

#include "native_engine_driver.hpp"

#include <cstdint>
#include <filesystem>
#include <stdexcept>
#include <string>
#include <vector>

namespace foundation::appended {

// Generated by the explicit native kernel producer from independently pinned
// retained inputs. These hashes and a valid source profile are declarations;
// this runtime integrity checker cannot qualify an engine or authenticate them.
struct NativeEngineLoadPins {
    engine_document::Digest recipe{}, binary_manifest{}, proof{}, runtime{};
};
enum class NativeEngineLoadAssetKind { file, directory };
struct NativeEngineLoadAsset {
    std::string path; // Exact portable relative path, using '/'.
    NativeEngineLoadAssetKind kind{NativeEngineLoadAssetKind::file};
    std::uint32_t logical_mode{}; // 0644/0755 files, 0755 directories.
    std::uint64_t bytes{}; // Directories have zero bytes and digest.
    engine_document::Digest sha256{};
};
struct NativeEngineLoadPlan {
    std::uint32_t schema_version{1};
    NativeEngineLoadPins pins;
    NativeEngineExpectation expectation;
    std::filesystem::path root; // Explicit absolute ordinary installed root.
    std::string provider_entry;
    // Complete sorted inventory, including every parent, metadata and notice.
    // On Windows logical modes come solely from this compiled producer plan.
    std::vector<NativeEngineLoadAsset> assets;
    std::vector<std::string> notices; // Sorted nonempty subset of regular files.
};
class NativeEngineLoadError : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

// Checks byte/path/mode consistency only, including the complete installed
// closure. The trusted producer/caller must keep it quiescent during loading.
// Admission selects exactly one independent ABI1.1 source profile: pixel1795
// or document-actions4083. All inactive profile facts must remain default.
// The shared load plan and provider are identical for bitmap and TUI callers.
void verify_native_engine_load_plan(const NativeEngineLoadPlan&);

// Resolves only bib_engine_get_provider_v1 in the explicit absolute entry and
// checks the actual table before any START. Never searches for another provider,
// invokes build tools, starts an engine or unloads an acquired OS handle, even
// after getter/table/integrity failure. The OS retains every handle until exit.
// Qualified native dependency resolution/private C++ runtime isolation remain
// retained-producer prerequisites; RTLD_LOCAL is not evidence for either.
[[nodiscard]] NativeEngineProvider load_native_engine(const NativeEngineLoadPlan&);

} // namespace foundation::appended
